"""Curated event-ledger extraction for criteria judging.

Takes typed Rasa tracker events and produces a compact, turn-anchored
timeline of behind-the-scenes events that an LLM judge can use as
evidence alongside the user-visible transcript.

Input is a list of typed :class:`~rasa.shared.core.events.Event` objects.
The runner is responsible for fetching the tracker and parsing the raw wire
dicts once via ``rasa.shared.core.events.deserialise_events`` (the same typed
events the assertion engine consumes); this module then dispatches on the
event subclass with ``isinstance`` and reads typed attributes, so an attribute
rename in ``events.py`` is caught by the type checker / IDE rather than
silently producing a blank field.

The filter is built from three layers, in order:

1. **Type allowlist** (implicit). Only these subclasses get rendered:
   :class:`FlowStarted` / :class:`FlowCompleted`, :class:`ActionExecuted`,
   the skill lifecycle (:class:`SkillActivated` etc.), the ordered-block
   lifecycle (:class:`OrderedBlockEntered` etc.), memory writes
   (:class:`SlotSet`, :class:`MemorySet`, :class:`MemoryCleared`), the
   sub-agent lifecycle (:class:`AgentStarted` etc.), and tool runs
   (:class:`ToolExecuted` as ``tool:``, :class:`McpToolExecuted` as
   ``mcp_tool:``). Everything else (stack, featurization, ...) falls
   through the ``isinstance`` ladder and is dropped.

   Whatever is on the tracker is rendered as-is: CALM trackers yield
   ``flow_*`` / ``slot_set`` / ``mcp_tool:`` lines, Mantle trackers yield
   ``skill_*`` / ``memory_*`` / ``tool:`` lines.

2. **CALM-internal name deny-list** for action and flow events.
   These are framework-machinery names that fire on every turn and would
   flood the ledger with no signal: ``action_listen``, ``pattern_*``
   flows, ``utter_ask_*`` slot prompts, ``action_run_slot_rejections``,
   etc. The lists are small, universal across CALM bots, and mostly
   stable — they live in ``_CALM_INTERNAL_ACTIONS`` /
   ``_CALM_INTERNAL_PREFIXES``.

3. **Structural slot filter** (no name list). Applies to every memory write
   (``SlotSet``, ``MemorySet``, ``MemoryCleared``). Writes come in two
   flavours: session-init dumps (set before the first user turn) and real
   fills during the conversation. We use *position* to tell them apart — turn
   0 writes are dropped wholesale — instead of maintaining a bot-specific name
   list (``brand_*``, ``customer_*``, …). The only name-level filter is a tiny
   universal CALM-internal set (``flow_hashes``, ``dialogue_stack``, etc.), kept
   as a safety net.

Usage::

    from rasa.builder.copilot.mcp_server.tools.event_ledger import (
        build_event_ledger,
    )
    from rasa.shared.core.events import deserialise_events

    ledger = build_event_ledger(deserialise_events(tracker["events"]))
"""

from __future__ import annotations

import ast
import json
from typing import Any, Iterable, List, Optional, Tuple, Union

from rasa.shared.core.events import (
    ActionExecuted,
    AgentCancelled,
    AgentCompleted,
    AgentInterrupted,
    AgentResumed,
    AgentStarted,
    BotUttered,
    Event,
    FlowCompleted,
    FlowStarted,
    McpToolExecuted,
    MemoryCleared,
    MemorySet,
    OrderedBlockCancelled,
    OrderedBlockCompleted,
    OrderedBlockEntered,
    OrderedBlockInterrupted,
    OrderedBlockResumed,
    SkillActivated,
    SkillCancelled,
    SkillCompleted,
    SkillInterrupted,
    SkillResumed,
    SlotSet,
    ToolExecuted,
    UserUttered,
    is_memory_write_event,
)

# Union of the sub-agent lifecycle events the ledger renders.
_AgentEvent = Union[
    AgentStarted,
    AgentCompleted,
    AgentInterrupted,
    AgentCancelled,
    AgentResumed,
]
_ToolRunEvent = Union[McpToolExecuted, ToolExecuted]
_SkillEvent = Union[
    SkillActivated,
    SkillCompleted,
    SkillCancelled,
    SkillInterrupted,
    SkillResumed,
]
_OrderedBlockEvent = Union[
    OrderedBlockEntered,
    OrderedBlockCompleted,
    OrderedBlockCancelled,
    OrderedBlockInterrupted,
    OrderedBlockResumed,
]

# ---------------------------------------------------------------------------
# Layer 2 — CALM-internal name deny-list (for action / flow events).
# Layer 1 (the type allowlist) is the implicit isinstance ladder in
# _render_relevant_event; it has no constants of its own.
# ---------------------------------------------------------------------------

# CALM dispatcher / stack-machinery actions; fire on every turn.
_CALM_INTERNAL_ACTIONS: frozenset = frozenset(
    {
        "action_listen",
        "action_run_slot_rejections",
        "action_session_start",
        "action_session_end",
        "action_extract_slots",
        "action_back",
        "action_two_stage_fallback",
    }
)

# Prefixes that mark CALM-internal flows / actions:
#   ``pattern_*``  — CALM pattern flows (digression, repeat, completed, …)
#   ``utter_ask_*`` — slot-fill prompts (the ``slot`` event already shows
#                     what was eventually collected)
_CALM_INTERNAL_PREFIXES: Tuple[str, ...] = ("pattern_", "utter_ask_")

# ---------------------------------------------------------------------------
# Layer 3 — slot-name safety net (universal CALM internal slots only)
# ---------------------------------------------------------------------------

# Slots that store framework state, not user/bot data. Bot-specific
# session-init dumps (``brand_*``, ``customer_*``, ``is_authenticated``,
# …) are NOT listed here; they're filtered structurally by dropping all
# slot events in turn 0 (events before the first user message).
_CALM_INTERNAL_SLOTS: frozenset = frozenset(
    {
        "flow_hashes",
        "dialogue_stack",
        "session_started_metadata",
        "return_value",
        "knowledge_base_last_object",
        "knowledge_base_last_object_type",
        "knowledge_base_objects",
    }
)


def _is_calm_internal_action(name: str) -> bool:
    if not name:
        return True
    return name in _CALM_INTERNAL_ACTIONS or any(
        name.startswith(p) for p in _CALM_INTERNAL_PREFIXES
    )


def _is_calm_internal_flow(flow_id: str) -> bool:
    return not flow_id or flow_id.startswith("pattern_")


def split_into_turns(
    events: List[Event],
) -> List[Tuple[int, List[Event]]]:
    """Group events by user-turn index.

    Turn index 0 is everything before the first real user message. A new turn
    opens only for a ``UserUttered`` with non-empty text that does not start
    with ``/``. Synthetic events stay in the current turn.
    """
    groups: List[Tuple[int, List[Event]]] = []
    current: List[Event] = []
    turn_idx = 0
    groups.append((turn_idx, current))
    for event in events:
        if isinstance(event, UserUttered):
            text = (event.text or "").strip()
            if not text or text.startswith("/"):
                current.append(event)
                continue
            turn_idx += 1
            current = []
            groups.append((turn_idx, current))
            current.append(event)
        else:
            current.append(event)
    return groups


def user_message_from_turn_events(turn_events: List[Event]) -> str:
    """Return the real user message anchoring a turn, or an empty string."""
    for event in turn_events:
        if isinstance(event, UserUttered):
            text = (event.text or "").strip()
            if text and not text.startswith("/"):
                return text
    return ""


# ---------------------------------------------------------------------------
# Filtering & rendering
# ---------------------------------------------------------------------------


def _to_single_line(text: str) -> str:
    """Collapse all whitespace runs (incl. newlines/tabs) to single spaces.

    The ledger is line-based (one event per line); an embedded newline in a
    value would otherwise read as a new ledger entry.
    """
    return " ".join(text.split())


def _single_line_value(value: Any) -> str:
    """Full single-line representation of a value, with no truncation."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    rendered = (
        json.dumps(value, default=str)
        if isinstance(value, (list, dict))
        else str(value)
    )
    return _to_single_line(rendered)


def _short_value(value: Any, max_len: int = 80) -> str:
    """Compact, single-line representation of a slot/reason value."""
    rendered = _single_line_value(value)
    if len(rendered) > max_len:
        rendered = rendered[: max_len - 1] + "…"
    return rendered


def _short_args(arguments: Any, max_len: int = 80) -> str:
    """Compact ``k=v, k=v`` rendering of MCP tool-call arguments."""
    if not arguments or not isinstance(arguments, dict):
        return ""
    argument_parts = [
        f"{key}={_short_value(value, 40)}" for key, value in arguments.items()
    ]
    rendered = ", ".join(argument_parts)
    if len(rendered) > max_len:
        rendered = rendered[: max_len - 1] + "…"
    return rendered


_EMPTY_RESULT_TOKENS: frozenset = frozenset(
    {"", "{}", "[]", "null", "none", '""', "''"}
)
_ERROR_RESULT_KEYS: frozenset = frozenset({"error", "errors"})


def _try_parse_mapping(raw_string: str) -> Any:
    """Best-effort parse of a stringified result into a Python object.

    The ``result`` field is a *string* (``str(structuredContent)`` on the Rasa
    side), so it may be JSON (``{"error": "..."}``) or a Python ``repr``
    (``{'error': '...'}``). Try both; return ``None`` if neither parses.
    """
    for parser in (json.loads, ast.literal_eval):
        try:
            return parser(raw_string)
        except (ValueError, SyntaxError, TypeError):
            continue
    return None


def _summarize_mcp_result(result: Any) -> Optional[str]:
    """Return a short suspicion marker for a *non-error* tool result, or ``None``.

    Many MCP tools swallow a backend failure into a normal return value (an
    empty ``{}`` / ``[]``, or a dict carrying an ``error`` field) while the MCP
    ``isError`` flag stays ``False`` — so the tool looks like it succeeded. This
    surfaces that so the judge can catch a bot claiming a concrete result the
    tool never actually produced.

    Returns ``"empty"`` for an empty/blank result, ``"reports error"`` for a
    result whose payload carries a truthy ``error`` / ``errors`` field, else
    ``None`` (genuine-looking success).
    """
    if result is None:
        return "empty"
    result_str = str(result).strip()
    if result_str.lower() in _EMPTY_RESULT_TOKENS:
        return "empty"
    parsed = _try_parse_mapping(result_str)
    if isinstance(parsed, dict):
        if not parsed:
            return "empty"
        for key, value in parsed.items():
            if str(key).lower() in _ERROR_RESULT_KEYS and value:
                return "reports error"
    elif isinstance(parsed, (list, tuple)) and not parsed:
        return "empty"
    return None


def is_user_relevant_tool_run(event: Event) -> bool:
    """Return whether a tool run is evidence for the judge and for scoring.

    Framework calls other than ``search_knowledge`` and ``cannot_help`` are
    hidden. Historical ``McpToolExecuted`` events stay visible.
    """
    if isinstance(event, McpToolExecuted):
        return True
    if not isinstance(event, ToolExecuted):
        return False
    # ToolExecuted is Mantle-only. Importing the names here keeps a CALM
    # end-to-end run, which imports this module but never passes a
    # ToolExecuted, from loading rasa.mantle.
    from rasa.mantle.llm.tool_schemas import (
        FRAMEWORK_TOOL_NAMES,
        TOOL_CANNOT_HELP,
        TOOL_SEARCH_KNOWLEDGE,
    )

    hidden = FRAMEWORK_TOOL_NAMES - {TOOL_SEARCH_KNOWLEDGE, TOOL_CANNOT_HELP}
    return event.tool_name not in hidden


def _tool_run_ledger_prefix(event: _ToolRunEvent) -> str:
    if isinstance(event, ToolExecuted):
        return "tool"
    return "mcp_tool"


def _render_tool_run_event(event: _ToolRunEvent) -> str:
    """Render one tool-run event as one ledger line.

    Covers MCP-tooled sub-agents (``mcp_open_agent`` / ``mcp_task_agent``)
    and Mantle ``ToolExecuted`` (local builder tools and MCP). Direct
    evidence a tool ran — much stronger than a bot ``utter_*`` claiming it did.

    Reads typed attributes shared by tool-run events
    (``tool_name``, ``arguments``, ``result``, ``is_error``, ``error_message``).

    ``ToolExecuted`` uses ``tool:`` for both ``local`` and ``mcp`` sources.
    ``McpToolExecuted`` uses ``mcp_tool:``::

        tool: lock_card(card_id=42) → ok
        mcp_tool: get_bills(account_id=12345) → ok
        mcp_tool: get_bills(account_id=12345) → ok (empty)
        mcp_tool: get_bills(account_id=12345) → ok (reports error)
        mcp_tool: get_bills(account_id=12345) → ERROR: 500 Internal Server Error

    The ``(empty)`` / ``(reports error)`` markers flag a tool that the MCP
    layer reported as successful (``is_error`` is ``False``) but whose payload
    looks like a swallowed backend failure — a common hallucination trap.
    """
    prefix = _tool_run_ledger_prefix(event)
    name = (event.tool_name or "?").strip()
    argument_str = _short_args(event.arguments)
    if event.is_error:
        error_text = _short_value(event.error_message or "error", 80)
        return f"{prefix}: {name}({argument_str}) → ERROR: {error_text}"
    marker = _summarize_mcp_result(event.result)
    if marker:
        return f"{prefix}: {name}({argument_str}) → ok ({marker})"
    return f"{prefix}: {name}({argument_str}) → ok"


def _render_agent_event(event: _AgentEvent) -> str:
    """Render one of the five sub-agent lifecycle events.

    Emitted by ``rasa/core/policies/flows/agent_executor.py`` and the
    MCP / A2A protocol agents. These are the ground truth for "did the
    agent step actually run, complete, or get interrupted?".

    When the executor knows the agent's protocol it records it on the
    ``metadata.protocol`` of ``agent_started`` / ``agent_completed`` (one of
    ``mcp_open`` / ``mcp_task`` / ``a2a``). It is surfaced as a
    ``protocol=<family>`` suffix — ``mcp_open`` / ``mcp_task`` collapse to
    ``mcp`` since the judge only needs to know whether to expect ``mcp_tool``
    lines (MCP-tooled agents emit them; ``a2a`` agents do not).

    Reads typed attributes off the agent-lifecycle :class:`Event` subclasses
    (``agent_id``, ``flow_id``, plus ``status`` / ``reason`` where the subclass
    defines them).
    """
    agent_id = (event.agent_id or "?").strip()
    flow_id = (event.flow_id or "?").strip()
    # Collapse mcp_open / mcp_task → "mcp" (see docstring); raw value stays on
    # the event metadata for analytics/inspector.
    protocol = (event.metadata or {}).get("protocol")
    protocol_display = (
        "mcp" if protocol and str(protocol).startswith("mcp") else protocol
    )
    protocol_suffix = f", protocol={protocol_display}" if protocol_display else ""

    if isinstance(event, AgentStarted):
        return f"agent_started: {agent_id} (flow={flow_id}{protocol_suffix})"

    if isinstance(event, AgentCompleted):
        status = event.status
        status_suffix = f", status={status}" if status else ""
        return (
            f"agent_completed: {agent_id} "
            f"(flow={flow_id}{protocol_suffix}{status_suffix})"
        )

    if isinstance(event, AgentCancelled):
        reason = event.reason
        reason_suffix = f", reason={_short_value(reason, 60)}" if reason else ""
        return f"agent_cancelled: {agent_id} (flow={flow_id}{reason_suffix})"

    # agent_interrupted, agent_resumed
    return f"{event.type_name}: {agent_id} (flow={flow_id})"


def _render_skill_event(event: _SkillEvent) -> Optional[str]:
    """Render one skill lifecycle event as a ledger line, or ``None``."""
    skill_id = (event.skill_id or "").strip()
    if not skill_id:
        return None
    return f"{event.type_name}: {skill_id}"


def _render_ordered_block_event(event: _OrderedBlockEvent) -> Optional[str]:
    """Render one ordered-block lifecycle event as a ledger line."""
    skill_id = (event.skill_id or "").strip()
    block_id = (event.block_id or "").strip()
    if not skill_id or not block_id:
        return None
    return f"{event.type_name}: {skill_id}/{block_id}"


def _render_memory_write_for_judge(event: Event, turn_idx: int) -> Optional[str]:
    """Render a memory or slot write for the judge ledger, or ``None`` if dropped.

    Turn 0 is session-init (before ``user[1]``) and is dropped wholesale.
    """
    if not is_memory_write_event(event):
        return None
    if turn_idx == 0:
        return None
    name = (event.key or "").strip()
    if not name or name in _CALM_INTERNAL_SLOTS:
        return None
    if isinstance(event, MemoryCleared):
        return f"memory_cleared: {name}"
    if isinstance(event, MemorySet):
        return f"memory_set: {name} = {_short_value(event.value)}"
    return f"slot_set: {name} = {_short_value(event.value)}"


def _render_tool_run_for_judge(event: _ToolRunEvent) -> Optional[str]:
    """Render a user-relevant tool run, or ``None`` for a framework call."""
    if not is_user_relevant_tool_run(event):
        return None
    return _render_tool_run_event(event)


def _render_relevant_event(event: Event, turn_idx: int) -> Optional[str]:
    """Render a relevant event as a one-line ledger string, or ``None`` if dropped.

    Dispatches on the event subclass and applies the filter layers documented
    at the top of this module. Subclasses we don't render fall through the
    ``isinstance`` ladder to ``None``.
    """
    if isinstance(event, (FlowStarted, FlowCompleted)):
        flow_id = (event.flow_id or "").strip()
        if _is_calm_internal_flow(flow_id):
            return None
        return f"{event.type_name}: {flow_id}"

    if isinstance(event, ActionExecuted):
        name = (event.action_name or "").strip()
        if _is_calm_internal_action(name):
            return None
        return f"action: {name}"

    if isinstance(event, _SkillEvent):
        return _render_skill_event(event)

    if isinstance(event, _OrderedBlockEvent):
        return _render_ordered_block_event(event)

    if is_memory_write_event(event):
        return _render_memory_write_for_judge(event, turn_idx)

    if isinstance(event, (McpToolExecuted, ToolExecuted)):
        return _render_tool_run_for_judge(event)

    if isinstance(
        event,
        (
            AgentStarted,
            AgentCompleted,
            AgentInterrupted,
            AgentCancelled,
            AgentResumed,
        ),
    ):
        return _render_agent_event(event)

    return None


# ---------------------------------------------------------------------------
# Compression of repeated runs / repeated turns
# ---------------------------------------------------------------------------


def _collapse_repeated_lines(lines: List[str]) -> List[str]:
    """Collapse consecutive duplicate ledger lines within a single turn.

    Each repeated line becomes ``<line>  × N`` so the judge sees the
    repetition without paying tokens for each copy.
    """
    if not lines:
        return lines
    collapsed: List[str] = []
    previous_line: Optional[str] = None
    run_count = 0
    for line in lines:
        if line == previous_line:
            run_count += 1
            continue
        if previous_line is not None:
            collapsed.append(
                f"{previous_line}  × {run_count}" if run_count > 1 else previous_line
            )
        previous_line = line
        run_count = 1
    if previous_line is not None:
        collapsed.append(
            f"{previous_line}  × {run_count}" if run_count > 1 else previous_line
        )
    return collapsed


def _collapse_repeated_turn_groups(
    rendered_groups: List[Tuple[int, str, List[str]]],
) -> List[Tuple[int, str, List[str]]]:
    """Collapse consecutive turn groups whose ledger lines are identical.

    Stuck-loop scenarios produce the same internal event sequence on every
    turn. Collapse them into a single representative group with a count
    annotation appended to the header so the judge can see the repetition
    without paying tokens for each copy.
    """
    if not rendered_groups:
        return rendered_groups

    collapsed: List[Tuple[int, str, List[str]]] = []
    index = 0
    while index < len(rendered_groups):
        turn_idx, header, lines = rendered_groups[index]
        run_end = index
        while run_end + 1 < len(rendered_groups):
            next_turn, _next_header, next_lines = rendered_groups[run_end + 1]
            # Only collapse non-zero turns (turn 0 has different shape)
            # whose body matches verbatim.
            if turn_idx == 0 or next_turn == 0:
                break
            if next_lines != lines:
                break
            run_end += 1
        if run_end > index:
            total_turns = run_end - index + 1
            last_turn = rendered_groups[run_end][0]
            new_header = (
                f"{header}  (events repeat identically through "
                f"T{last_turn} — × {total_turns} turns total)"
            )
            collapsed.append((turn_idx, new_header, lines))
            index = run_end + 1
        else:
            collapsed.append((turn_idx, header, lines))
            index += 1
    return collapsed


# ---------------------------------------------------------------------------
# Debug formatting
# ---------------------------------------------------------------------------


def _format_debug_memory_event(event: Event) -> Optional[str]:
    """Render a ``MemorySet`` / ``MemoryCleared`` debug line, or ``None``."""
    if isinstance(event, MemoryCleared):
        return f"memory_cleared: {event.key}"
    if isinstance(event, MemorySet):
        return f"memory_set: {event.key} = {_single_line_value(event.value)}"
    return None


def _format_debug_skill_event(event: _SkillEvent) -> str:
    """Render a skill lifecycle event as a debug line, including optional step."""
    step_id = getattr(event, "step_id", None)
    if step_id:
        return f"{event.type_name}: {event.skill_id} (step={step_id})"
    return _render_skill_event(event) or f"{event.type_name}: {event.skill_id}"


def _format_debug_ordered_block_event(event: _OrderedBlockEvent) -> str:
    """Render an ordered-block lifecycle event as ``type: skill/block``."""
    line = f"{event.type_name}: {event.skill_id}/{event.block_id}"
    step_id = getattr(event, "step_id", None)
    if step_id:
        return f"{line} (step={step_id})"
    return line


def _format_debug_event_line(event: Event) -> str:
    """Render one tracker event as a single debug line, in full — no truncation."""
    if isinstance(event, UserUttered):
        return f"user: {_single_line_value((event.text or '').strip())!r}"
    if isinstance(event, BotUttered):
        return f"agent: {_single_line_value((event.text or '').strip())!r}"
    if isinstance(event, ActionExecuted):
        return f"action: {event.action_name}"
    if isinstance(event, SlotSet):
        return f"slot: {event.key} = {_single_line_value(event.value)}"
    memory_line = _format_debug_memory_event(event)
    if memory_line is not None:
        return memory_line
    if isinstance(event, FlowStarted):
        return f"flow_started: {event.flow_id}"
    if isinstance(event, FlowCompleted):
        return f"flow_completed: {event.flow_id}"
    if isinstance(event, _SkillEvent):
        return _format_debug_skill_event(event)
    if isinstance(event, _OrderedBlockEvent):
        return _format_debug_ordered_block_event(event)
    if isinstance(event, (McpToolExecuted, ToolExecuted)):
        return _render_tool_run_event(event)
    if isinstance(event, _AgentEvent):
        agent_id = getattr(event, "agent_id", None)
        flow_id = getattr(event, "flow_id", None)
        detail = agent_id or flow_id or ""
        return f"{event.type_name}: {detail}"
    # Debug dump shows every event in full — unlike the compact ledger's
    # `_short_value`, this must not truncate the payload.
    payload = event.as_dict()
    payload.pop("timestamp", None)
    return f"{event.type_name}: {_single_line_value(payload)}"


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def _format_turn_header(turn_idx: int, user_message: str) -> str:
    """Build a turn header matching the event-ledger ``[Tn]`` conventions."""
    if turn_idx == 0:
        return "[pre-T1]  (events before first user turn)"
    if user_message:
        return f'[T{turn_idx}] user: "{_short_value(user_message, 200)}"'
    return f"[T{turn_idx}]"


def _ledger_lines_for_turn(
    turn_idx: int,
    turn_events: List[Event],
    *,
    include_bot_text: bool,
) -> List[str]:
    """Build indented ledger lines for one turn's filtered events."""
    ledger_lines: List[str] = []
    for event in turn_events:
        if isinstance(event, UserUttered):
            # User text is rendered in the turn header; never inline.
            continue
        if isinstance(event, BotUttered) and include_bot_text:
            text = (event.text or "").strip()
            if text:
                ledger_lines.append(f"  agent: {_short_value(text, 200)!r}")
            continue
        line = _render_relevant_event(event, turn_idx)
        if line is None:
            continue
        ledger_lines.append(f"  {line}")
    return ledger_lines


def _turn_header_for_ledger(
    turn_idx: int,
    turn_events: List[Event],
    *,
    include_user_text: bool,
) -> str:
    """Build the turn header for one ledger group."""
    user_text = user_message_from_turn_events(turn_events) if include_user_text else ""
    return _format_turn_header(turn_idx, user_text)


def _build_rendered_turn_groups(
    grouped: List[Tuple[int, List[Event]]],
    *,
    include_user_text: bool,
    include_bot_text: bool,
    drop_repeated_runs: bool,
) -> List[Tuple[int, str, List[str]]]:
    """Render filtered ledger lines for each turn group."""
    rendered_groups: List[Tuple[int, str, List[str]]] = []
    for turn_idx, turn_events in grouped:
        ledger_lines = _ledger_lines_for_turn(
            turn_idx, turn_events, include_bot_text=include_bot_text
        )
        if drop_repeated_runs:
            ledger_lines = _collapse_repeated_lines(ledger_lines)

        # Skip turn groups that produced no meaningful events at all
        # (e.g. turn 0 with only session-start slot dumps that we dropped).
        if not ledger_lines:
            continue

        header = _turn_header_for_ledger(
            turn_idx, turn_events, include_user_text=include_user_text
        )
        rendered_groups.append((turn_idx, header, ledger_lines))
    return rendered_groups


def _assemble_ledger_output(
    rendered_groups: List[Tuple[int, str, List[str]]],
) -> str:
    """Join rendered turn groups into the final multi-line ledger string."""
    out_lines: List[str] = []
    for _, header, lines in rendered_groups:
        out_lines.append(header)
        out_lines.extend(lines)
    return "\n".join(out_lines)


def build_event_ledger(
    events: Iterable[Event],
    *,
    include_user_text: bool = True,
    include_bot_text: bool = False,
    drop_repeated_runs: bool = True,
    collapse_repeated_turns: bool = True,
) -> str:
    """Build a turn-anchored, compressed event ledger string.

    Args:
        events: Typed tracker events, e.g.
            ``deserialise_events(tracker["events"])``.
        include_user_text: If True, anchor each turn group with the
            user's verbatim message. Defaults to True so the ledger is
            self-describing even when consumed without an accompanying
            transcript.
        include_bot_text: If True, also include bot utterances inline.
            Off by default — bot text is in the transcript.
        drop_repeated_runs: When the same event line repeats consecutively
            within a single turn, collapse to ``× N`` markers. Defaults
            to True.
        collapse_repeated_turns: When consecutive turn groups have
            identical event contents (stuck loops), collapse them into a
            single entry with a count. Defaults to True.

    Returns:
        A multi-line ledger like::

            [T1] user: "I'd like to access my account."
              flow_started: online_accounts
              slot_set: online_account = "password_reset" (filled_by=LLM)
              action: utter_password_reset
              flow_completed: online_accounts
            [T2] user: "Thank you."
              ...

        Empty string if ``events`` is empty or no event survives filtering.
    """
    events_list = list(events)
    if not events_list:
        return ""
    grouped = split_into_turns(events_list)
    rendered_groups = _build_rendered_turn_groups(
        grouped,
        include_user_text=include_user_text,
        include_bot_text=include_bot_text,
        drop_repeated_runs=drop_repeated_runs,
    )
    if collapse_repeated_turns:
        rendered_groups = _collapse_repeated_turn_groups(rendered_groups)
    return _assemble_ledger_output(rendered_groups)


def format_tracker_events_debug(events: Iterable[Event]) -> str:
    """Format every tracker event grouped by user turn for debugging.

    Unlike :func:`build_event_ledger`, nothing is filtered — every event in
    the tracker is shown. Turn headers use the same ``[Tn]`` indexing as
    :func:`split_into_turns`.

    Args:
        events: Typed tracker events.

    Returns:
        Multi-line debug dump grouped by user turn.
    """
    events_list = list(events)
    if not events_list:
        return "(no tracker events)"

    lines: List[str] = []
    for turn_idx, turn_events in split_into_turns(events_list):
        lines.append(
            _format_turn_header(turn_idx, user_message_from_turn_events(turn_events))
        )
        for index, event in enumerate(turn_events, start=1):
            lines.append(f"  {index:3d}  {_format_debug_event_line(event)}")

    return "\n".join(lines)
